// Validate the token: must exist, not be expired, not be consumed.
const token = $('Webhook').first().json.query.token;
const rows = items.map(i => i.json).filter(r => r && r.token);
const row = rows.find(r => r.token === token) || null;

let valid = false;
let reason = 'not_found';

if (row) {
  const consumed = row.consumed === true || row.consumed === 'true';
  const expired = row.expiresAt ? new Date(row.expiresAt).getTime() < Date.now() : false;
  if (consumed) reason = 'already_consumed';
  else if (expired) reason = 'expired';
  else { valid = true; reason = 'ok'; }
}

return [{ json: { ...(row || {}), token, valid, reason, locale: (row && row.locale) || 'nl' } }];

// Consumes the five validated JSON sections. Formatting lives here, not in the prompt -
// the model returns content only. Values are escaped: Christel's prose contains & and
// quotes, which would otherwise break the document.
const p = $('Validate Token').first().json;
const r = $json.report;
const SECTIONS = ['opening', 'reaction', 'origin', 'cost', 'closing'];

const heading = p.locale === 'en' ? 'Your NEM Test report' : 'Jouw NEM Test rapport';
const greeting = p.locale === 'en' ? 'Dear' : 'Beste';

const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const para = (t) => esc(t)
  .split(/\n{2,}/)
  .map(x => '<p>' + x.replace(/\n/g, '<br>') + '</p>')
  .join('');

const body = SECTIONS.map(k => para(r[k])).join('');
const reportText = SECTIONS.map(k => r[k]).join('\n\n');

const html = '<!doctype html><html><head><meta charset="utf-8"><style>'
  + 'body{font-family:Georgia,serif;color:#292828;max-width:640px;margin:0 auto;padding:48px 40px;line-height:1.6;font-size:16px}'
  + 'h1{font-family:Montserrat,Arial,sans-serif;font-size:24px;color:#292828}'
  + 'p{margin:0 0 16px}'
  + '</style></head><body><h1>' + heading + '</h1>'
  + '<p>' + greeting + ' ' + esc(p.firstName || '') + ',</p>'
  + body
  + '</body></html>';

return [{ json: Object.assign({ html: html, reportText: reportText }, p) }];

// Base64-encode the PDFShift binary so MailerSend can attach it.
const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({ json: { ...items[i].json, pdfBase64: buf.toString('base64') } });
}
return out;

// Validates the report JSON contract. Mirror of projects/nem-life/src/nem-report-parse.js,
// which is unit-tested in tests/nem/nem-report-parse.test.js - keep the two in step.
// This is a gate on the live report path: anything rejected here means the user gets
// nothing, so it is strict about shape and tolerant about presentation.
const REPORT_KEYS = ['opening', 'reaction', 'origin', 'cost', 'closing'];
const RAW_LIMIT = 2000;

function extractText(response) {
  const blocks = response && response.content;
  if (!Array.isArray(blocks)) return null;
  const text = blocks
    .filter(b => b && b.type === 'text' && typeof b.text === 'string')
    .map(b => b.text)
    .join('');
  return text.length > 0 ? text : null;
}

function unwrap(text) {
  const trimmed = text.trim();
  const fenced = /^```[a-zA-Z]*\s*\n?([\s\S]*?)\n?```$/.exec(trimmed);
  return (fenced ? fenced[1] : trimmed).trim();
}

function isPlainObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function fail(reason, detail, raw) {
  return {
    valid: false,
    reason: reason,
    detail: detail,
    raw: String(raw == null ? '' : raw).slice(0, RAW_LIMIT)
  };
}

function parseReport(response) {
  const text = extractText(response);
  // Checked before parsing: truncated JSON fails to parse anyway, but "unexpected end of
  // input" tells nobody what to change, whereas this points straight at max_tokens.
  if (response && response.stop_reason === 'max_tokens') {
    return fail('truncated', 'Anthropic stopped at max_tokens - the report was cut short. Raise max_tokens or shorten the prompt.', text);
  }
  if (text === null) return fail('not-json', 'No text block in the model response.', '');
  let parsed;
  try {
    parsed = JSON.parse(unwrap(text));
  } catch (e) {
    return fail('not-json', 'Response is not valid JSON: ' + e.message, text);
  }
  if (!isPlainObject(parsed)) {
    return fail('not-json', 'Parsed to ' + (Array.isArray(parsed) ? 'an array' : typeof parsed) + ', expected an object.', text);
  }
  const missing = REPORT_KEYS.filter(k => !(k in parsed));
  if (missing.length > 0) return fail('missing-key', 'Missing: ' + missing.join(', ') + '.', text);
  const empty = REPORT_KEYS.filter(k => typeof parsed[k] !== 'string' || parsed[k].trim().length === 0);
  if (empty.length > 0) return fail('empty-value', 'Empty or non-string: ' + empty.join(', ') + '.', text);
  const report = {};
  for (const k of REPORT_KEYS) report[k] = parsed[k];
  return { valid: true, report: report };
}

const result = parseReport($json);
const p = $('Validate Token').first().json;

return [{
  json: Object.assign({}, p, {
    parseValid: result.valid,
    report: result.valid ? result.report : null,
    reason: result.valid ? '' : result.reason,
    detail: result.valid ? '' : result.detail,
    rawResponse: result.valid ? '' : result.raw,
    executionId: String($execution.id),
    failedAt: new Date().toISOString()
  })
}];
